use std::collections::HashMap;
use std::io::Read;

// ──────────────────────────────────────────────────────────────────────────
// Constants
// ──────────────────────────────────────────────────────────────────────────

const MAX_RETRIES: u32 = 3;
const DEFAULT_TIMEOUT: u64 = 30;

// ──────────────────────────────────────────────────────────────────────────
// Core Types
// ──────────────────────────────────────────────────────────────────────────

pub struct Config {
    retries: u32,
    timeout: u64,
}

pub enum Status {
    Active,
    Inactive,
}

// ──────────────────────────────────────────────────────────────────────────
// Trait Definitions
// ──────────────────────────────────────────────────────────────────────────

pub trait Validate {
    fn validate(&self) -> bool;
}

// ============================================================================
// END SETUP
// ============================================================================

// ============================================================================
// BODY
// ============================================================================

impl Config {
    pub fn new() -> Self {
        Config {
            retries: MAX_RETRIES,
            timeout: DEFAULT_TIMEOUT,
        }
    }
}

impl Validate for Config {
    fn validate(&self) -> bool {
        self.retries > 0 && self.timeout > 0
    }
}

pub fn process(config: &Config) -> Status {
    if config.validate() {
        Status::Active
    } else {
        Status::Inactive
    }
}

